INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1), 'شركة مقاولات اشترت لودر عشان تستخدمه في مشروعاتها لمدة 6 سنين. اللودر ده يتبع أنهي معيار؟', '["IAS 2 المخزون","IAS 16 العقارات والآلات والمعدات","IAS 40 الاستثمار العقاري","IAS 38 الأصول غير الملموسة"]', 1, 'أصل ملموس مستخدم في النشاط لأكتر من فترة مالية (IAS 16.6).' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1) AND body = 'شركة مقاولات اشترت لودر عشان تستخدمه في مشروعاتها لمدة 6 سنين. اللودر ده يتبع أنهي معيار؟'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1), 'شرط المنافع الاقتصادية للاعتراف بأصل ثابت حسب IAS 16 هو إن المنافع تكون:', '["مؤكدة 100%","مضمونة بعقد مكتوب","ممكنة ولو باحتمال ضعيف","محتملة (Probable)"]', 3, 'المعيار بيطلب إن تدفق المنافع يكون محتمل، مش مؤكد (IAS 16.7).' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1) AND body = 'شرط المنافع الاقتصادية للاعتراف بأصل ثابت حسب IAS 16 هو إن المنافع تكون:'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 1), 'ماكينة سعرها 600,000 جنيه بخصم تجاري 5%، وعليها ضريبة قيمة مضافة 14% قابلة للخصم، ونقل 20,000، وتركيب 30,000، وتدريب عمال 10,000. تكلفة الماكينة:', '["650,000 جنيه","630,000 جنيه","699,800 جنيه","620,000 جنيه"]', 3, '570,000 + 20,000 + 30,000 = 620,000. الضريبة القابلة للخصم والتدريب مايدخلوش (IAS 16.16 و16.19).' WHERE N